using System;
using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEngine;
using Steria.Vfx;
using Object = UnityEngine.Object;

public static class ChristashaNativePiercePreview
{
 static string Arg(string n){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,n);if(i<0||i+1==a.Length)throw new ArgumentException(n);return a[i+1];}
 public static void Render(){try{
  string output=Arg("-candidateOutput");Directory.CreateDirectory(output);var bundle=AssetBundle.LoadFromFile(Arg("-referenceBundle"));if(bundle==null)throw new Exception("Missing reference bundle");
  Func<string,GameObject> resolver=p=>bundle.LoadAsset<GameObject>("assets/native_reference/"+p.Substring(p.LastIndexOf('/')+1)+".prefab");
  string brushPath="Assets/NativeRuntime/tide-brush-imagegen-v1.png";var imp=AssetImporter.GetAtPath(brushPath) as TextureImporter;imp.sRGBTexture=false;imp.isReadable=true;imp.wrapMode=TextureWrapMode.Clamp;imp.mipmapEnabled=false;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.SaveAndReimport();var brush=AssetDatabase.LoadAssetAtPath<Texture2D>(brushPath);
  using(var library=new ChristashaNativePierceRecipes(resolver,brush)){
   foreach(var recipe in new[]{"Pierce","Projectile"}){var candidate=library.CreatePrototype(recipe);candidate.SetActive(false);Check(candidate,recipe,output);Capture(candidate,recipe,Path.Combine(output,recipe));Object.DestroyImmediate(candidate);}
  }
  bundle.Unload(true);File.WriteAllText(Path.Combine(output,"complete.txt"),"PIERCE_NATIVE_REPLAY_PASS\n"+Application.unityVersion+" / "+SystemInfo.graphicsDeviceType+"\nDagger native visual replay; independent art review required.");Debug.Log("CHRISTASHA_NATIVE_PIERCE_PREVIEW_PASS");
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Check(GameObject go,string recipe,string output){if(go.GetComponentsInChildren<MonoBehaviour>(true).Length!=0)throw new Exception("Unexpected scripts");int childCount=go.GetComponentsInChildren<Transform>(true).Length;go.SetActive(true);var hooks=ChristashaNativePierceRecipes.TryCreatePlayback(go,19037u);if(hooks==null)throw new Exception("Missing Pierce hooks");var systems=go.GetComponentsInChildren<ParticleSystem>(true);var anim=go.GetComponentsInChildren<Animator>(true);Manual(hooks,systems,anim,.11f);string snap=Snapshot(go);hooks.StopAndClear();foreach(var p in systems)if(p.particleCount!=0)throw new Exception("cancel left particles");var replay=Object.Instantiate(go);replay.SetActive(true);ResetAnimators(replay);var replayHooks=ChristashaNativePierceRecipes.TryCreatePlayback(replay,19037u);Manual(replayHooks,replay.GetComponentsInChildren<ParticleSystem>(true),replay.GetComponentsInChildren<Animator>(true),.11f);if(Snapshot(replay)!=snap)throw new Exception("replay mismatch");replayHooks.StopAndClear();Object.DestroyImmediate(replay);go.SetActive(false);if(go.GetComponentsInChildren<Transform>(true).Length!=childCount)throw new Exception("hierarchy grew");File.WriteAllText(Path.Combine(output,recipe+"-focused-checks.txt"),"PASS scripts/cancel/replay/hierarchy; native source unchanged checked by resolver identity.\n"+snap);}
 static void ResetAnimators(GameObject root){foreach(var a in root.GetComponentsInChildren<Animator>(true)){a.fireEvents=false;a.applyRootMotion=false;a.cullingMode=AnimatorCullingMode.AlwaysAnimate;a.speed=0;if(a.enabled&&a.gameObject.activeInHierarchy){a.Rebind();a.Update(0);}}}
 static void Manual(IChristashaNativePlaybackHooks h,ParticleSystem[] ps,Animator[] anim,float duration){float e=0,step=1f/120f;while(e<duration){float dt=Mathf.Min(step,duration-e);h.BeforeAnimator(dt,e);foreach(var a in anim){a.speed=1;a.Update(dt);a.speed=0;}h.AfterAnimator(dt,e);foreach(var p in ps){if(p.gameObject.activeInHierarchy)p.Simulate(dt,false,false,false);p.Pause(false);}e+=dt;h.AfterParticles(dt,e);foreach(var p in ps){if(p.gameObject.activeInHierarchy)p.Simulate(0,false,false,false);p.Pause(false);}}}
 static string Snapshot(GameObject root){var l=new List<string>();foreach(var p in root.GetComponentsInChildren<ParticleSystem>(true)){var a=new ParticleSystem.Particle[p.main.maxParticles];int n=p.GetParticles(a);l.Add(p.name+"="+n);for(int i=0;i<n;i++)l.Add(a[i].position.ToString("F4")+a[i].remainingLifetime.ToString("F4"));}return string.Join("\n",l.ToArray());}
 static void Capture(GameObject root,string recipe,string output){Directory.CreateDirectory(output);root.SetActive(true);foreach(var t in root.GetComponentsInChildren<Transform>(true))t.gameObject.layer=30;var camGO=new GameObject("PierceCamera");var cam=camGO.AddComponent<Camera>();cam.enabled=false;cam.orthographic=true;cam.orthographicSize=2.2f;cam.transform.position=new Vector3(-1f,0,-100);cam.aspect=16f/9f;cam.clearFlags=CameraClearFlags.SolidColor;cam.cullingMask=1<<30;cam.allowHDR=true;cam.nearClipPlane=.01f;cam.farClipPlane=500f;var rt=new RenderTexture(960,540,24,RenderTextureFormat.ARGB32);rt.Create();cam.targetTexture=rt;var tex=new Texture2D(960,540,TextureFormat.RGB24,false);var hooks=ChristashaNativePierceRecipes.TryCreatePlayback(root,19037u);var timeline=new List<string>{"frame,time,particles"};float age=0f;var metadata=new List<string>{"Dagger native resources, camera ortho8 at (-1,0,-100), 960x540, 60fps, manual 120Hz-equivalent steps; source direction -X for Projectile demonstrator.","Raw art scales: Pierce=(1,1,1), Projectile=(.92,.92,.92); effective clocks Pierce=.68s / Projectile=.32s at 0.91 speed; core starts 0.012s, support bundles stagger through 0.33s; Projectile primary burst completes before .26s."};foreach(var p in root.GetComponentsInChildren<ParticleSystem>(true))foreach(var m in p.GetComponent<ParticleSystemRenderer>().sharedMaterials)if(m!=null)metadata.Add(p.name+" material="+m.name+" shader="+m.shader.name+" supported="+m.shader.isSupported+" _Color="+(m.HasProperty("_Color")?m.GetColor("_Color").ToString():"n/a")+" _MainColor="+(m.HasProperty("_MainColor")?m.GetColor("_MainColor").ToString():"n/a")+" alphaPropsPreserved=true");for(int frame=0;frame<=36;frame++){if(frame>0){ManualStep(hooks,root,1f/60f,age+1f/60f);age+=1f/60f;}int count=0;foreach(var p in root.GetComponentsInChildren<ParticleSystem>(true))count+=p.particleCount;timeline.Add(frame+","+(frame/60f).ToString(System.Globalization.CultureInfo.InvariantCulture)+","+count);if(frame==1||frame==3||frame==6||frame==10){foreach(var q in root.GetComponentsInChildren<ParticleSystem>(true)){var b=new MaterialPropertyBlock();q.GetComponent<ParticleSystemRenderer>().GetPropertyBlock(b);metadata.Add("ACTUAL f="+frame+" "+q.name+" _Color="+b.GetColor("_Color")+" _MainColor="+b.GetColor("_MainColor")+" MainColor="+b.GetColor("MainColor")+" alpha-preserve=true");}}for(int bg=0;bg<2;bg++){cam.backgroundColor=bg==0?new Color(.035f,.045f,.06f):new Color(.32f,.34f,.37f);cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,960,540),0,0);tex.Apply();File.WriteAllBytes(Path.Combine(output,(bg==0?"dark_":"mid_")+frame.ToString("D4")+".png"),tex.EncodeToPNG());}}File.WriteAllLines(Path.Combine(output,"timeline.csv"),timeline);File.WriteAllLines(Path.Combine(output,"metadata.txt"),metadata);hooks.StopAndClear();RenderTexture.active=null;cam.targetTexture=null;Object.DestroyImmediate(tex);Object.DestroyImmediate(rt);Object.DestroyImmediate(camGO);}
 static void ManualStep(IChristashaNativePlaybackHooks h,GameObject root,float dt,float age){h.BeforeAnimator(dt,age);foreach(var a in root.GetComponentsInChildren<Animator>(true)){a.speed=1;a.Update(dt);a.speed=0;}h.AfterAnimator(dt,age);foreach(var p in root.GetComponentsInChildren<ParticleSystem>(true)){if(p.gameObject.activeInHierarchy)p.Simulate(dt,false,false,false);p.Pause(false);}h.AfterParticles(dt,age);foreach(var p in root.GetComponentsInChildren<ParticleSystem>(true)){if(p.gameObject.activeInHierarchy)p.Simulate(0,false,false,false);p.Pause(false);}}
}
